{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Collect Review Inputs",
        "actor": "Document Reviewer",
        "system": "Document Repository",
        "inputs": ["Specification Document (current version)", "Previous Document Version", "Feature Change List", "Review Checklist"],
        "outputs": ["Collected Review Package"]
