      {
        "id": "A2",
        "name": "Review Feature Coverage",
        "actor": "Document Reviewer",
        "system": "Document Repository / Commenting Tool",
        "inputs": ["Collected Review Package", "Review Checklist"],
        "outputs": ["Feature Coverage Assessment", "Review Comments (feature gaps)"]
      },
      {
        "id": "A3",
        "name": "Review Terminology and Formatting Consistency",
        "actor": "Document Reviewer",
        "system": "Commenting Tool",
        "inputs": ["Specification Document (current version)", "Review Checklist"],
        "outputs": ["Terminology and Formatting Assessment", "Review Comments (style issues)"]
      },
      {
        "id": "A4",
        "name": "Record Review Comments and Change Requests",
        "actor": "Document Reviewer",
        "system": "Commenting Tool / Change Request Tracker",
        "inputs": ["Review Comments (feature gaps)", "Review Comments (style issues)"],
        "outputs": ["Consolidated Review Comments", "Change Request List"]
      },
      {
        "id": "A5",
        "name": "Request Document Revision",
        "actor": "Document Reviewer",
        "system": "Change Request Tracker",
        "inputs": ["Change Request List"],
        "outputs": ["Revision Request to Document Author"]
      },
      {
        "id": "A6",
        "name": "Revise Specification Document",
        "actor": "Document Author",
        "system": "Document Repository / Commenting Tool",
        "inputs": ["Revision Request to Document Author", "Change Request List", "Specification Document (current version)"],
        "outputs": ["Revised Specification Document"]
      },
      {
        "id": "A7",
        "name": "Confirm Revisions (Feature Owner)",
        "actor": "Feature Owner",
        "system": "Document Repository / Change Request Tracker",
        "inputs": ["Revised Specification Document", "Feature Change List"],
        "outputs": ["Feature Owner Confirmation"]
      },
      {
        "id": "A8",
        "name": "Approve Final Document",
        "actor": "Approver",
        "system": "Document Repository",
        "inputs": ["Revised Specification Document", "Feature Owner Confirmation", "Consolidated Review Comments"],
        "outputs": ["Approved Specification Document"]
      },
      {
        "id": "A9",
        "name": "Request Further Revision",
        "actor": "Approver",
        "system": "Change Request Tracker / Commenting Tool",
        "inputs": ["Revised Specification Document", "Approver Review Findings"],
        "outputs": ["Additional Change Request List"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Are all feature changes fully reflected in the specification document?",
        "branches": [
          {
            "outcome": "No — feature changes missing",
            "next": "A5"
          },
          {
            "outcome": "Yes — feature coverage complete",
            "next": "A3"
          }
        ]
      },
      {
        "id": "D2",
        "condition": "Does the approver accept the revised document?",
        "branches": [
          {
            "outcome": "Yes — document approved",
            "next": "A8"
          },
          {
            "outcome": "No — further revision required",
            "next": "A9"
          }
        ]
      }
    ],
    "exceptions": [
      {
        "id": "E1",
        "description": "Unresolved review comments — one or more comments raised by the reviewer cannot be resolved and remain open; no defined escalation or resolution path is specified."
      },
      {
        "id": "E2",
        "description": "Non-response from Document Author or Feature Owner — no defined timeout or escalation procedure exists if a party does not respond within a given timeframe."
      },
      {
        "id": "E3",
        "description": "Reviewer disagreement — no defined process exists if multiple reviewers or stakeholders disagree on the required changes."
      }
    ],
    "dependencies": [
      {"from": "A1", "to": "A2", "type": "control_flow"},
      {"from": "A2", "to": "D1", "type": "control_flow"},
      {"from": "D1", "to": "A3", "type": "control_flow"},
      {"from": "D1", "to": "A5", "type": "control_flow"},
      {"from": "A3", "to": "A4", "type": "control_flow"},
      {"from": "A4", "to": "D1", "type": "data_flow"},
      {"from": "A5", "to": "A6", "type": "control_flow"},
      {"from": "A9", "to": "A6", "type": "control_flow"},
      {"from": "A6", "to": "A7", "type": "control_flow"},
      {"from": "A7", "to": "D2", "type": "control_flow"},
      {"from": "D2", "to": "A8", "type": "control_flow"},
      {"from": "D2", "to": "A9", "type": "control_flow"}
    ]
  },
  "automation_opportunities": [
    {
      "target": "A2 — Review Feature Coverage",
      "rationale": "A script or NLP-based tool could automatically cross-reference the feature change list against the specification document text to flag missing or partially covered features, reducing manual reading effort.",
      "required_data": ["Structured or machine-readable feature change list", "Parseable specification document format"],
      "constraints": ["Feature change list must be in a consistent structured format", "Document must be in a text-extractable format (e.g., not scanned PDF)", "NLP accuracy may require human validation of edge cases"],
      "confidence": "medium"
    },
    {
      "target": "A3 — Review Terminology and Formatting Consistency",
      "rationale": "Automated linting tools or style checkers can detect terminology inconsistencies, spelling errors, and formatting deviations against a defined style guide or glossary without manual inspection.",
      "required_data": ["Defined terminology glossary", "Formatting style guide or rules", "Machine-readable specification document"],
      "constraints": ["Style guide must be codified in a machine-readable form", "Domain-specific terminology may require custom dictionary maintenance"],
      "confidence": "high"
    },
    {
      "target": "A4 — Record Review Comments and Change Requests",
      "rationale": "Automated aggregation of inline comments from the commenting tool into the change request tracker can eliminate manual transcription, reduce errors, and create a consistent audit trail.",
      "required_data": ["API or integration between commenting tool and change request tracker", "Structured comment format with category tags"],
      "constraints": ["Requires integration capability between the two systems", "Comment categorization (feature gap vs. style) may need manual tagging or classification"],
      "confidence": "medium"
    },
    {
      "target": "D1 — Are all feature changes fully reflected?",
      "rationale": "If feature coverage checking (A2) is automated, the decision outcome can be derived programmatically from the coverage report, routing the workflow automatically without manual reviewer judgment for clear-cut cases.",
      "required_data": ["Automated coverage report output", "Threshold or completeness criteria definition"],
      "constraints": ["Ambiguous or partially covered features will still require human judgment", "Completeness criteria must be formally defined"],
      "confidence": "low"
    },
